<script setup lang="ts">
import {reactive,ref} from 'vue'
import {HysSteps,HysSelect,HysCheckbox,HysButton,type HysStepStatus} from 'hys-ui'
const current=ref(1)
const config=reactive({status:'process' as HysStepStatus,size:'md' as 'sm'|'md',labelPlacement:'right' as 'right'|'bottom',vertical:false,clickable:true,progressDot:false,simple:false,responsive:true})
const items=[{title:'填写资料',description:'完善个人和联系信息'},{title:'确认内容',description:'核对输入内容'},{title:'完成',description:'确认后生效'}]
</script>
<template><div><div class="demo-controls"><section class="demo-control-section"><h3>外观与内容</h3><div class="demo-control-fields"><label class="demo-field"><span class="demo-control-label">当前状态 <code>status</code></span><HysSelect v-model="config.status" :options="['process','finish','error','wait'].map(value=>({label:value,value}))"/></label><label class="demo-field"><span class="demo-control-label">尺寸 <code>size</code></span><HysSelect v-model="config.size" :options="['sm','md'].map(value=>({label:value,value}))"/></label><label class="demo-field"><span class="demo-control-label">标题位置 <code>labelPlacement</code></span><HysSelect v-model="config.labelPlacement" :options="['right','bottom'].map(value=>({label:value,value}))"/></label></div></section><section class="demo-control-section"><h3>状态与行为</h3><div class="demo-control-toggles"><div class="demo-control-toggle"><HysCheckbox v-model="config.vertical" label="纵向"/><small>vertical</small></div><div class="demo-control-toggle"><HysCheckbox v-model="config.clickable" label="可切换步骤"/><small>clickable</small></div><div class="demo-control-toggle"><HysCheckbox v-model="config.progressDot" label="点状进度"/><small>progressDot</small></div><div class="demo-control-toggle"><HysCheckbox v-model="config.simple" label="简洁显示"/><small>simple</small></div><div class="demo-control-toggle"><HysCheckbox v-model="config.responsive" label="窄屏纵向排列"/><small>responsive</small></div></div></section></div><div class="demo-content"><HysSteps v-model:current="current" v-bind="config" :items="items"/><div class="demo-row"><HysButton variant="secondary" :disabled="current<=0" @click="current--">上一步</HysButton><HysButton :disabled="current>=items.length" @click="current++">{{current===items.length-1?'完成':'下一步'}}</HysButton></div></div><output class="state-output">当前步骤：{{current}}（从 0 开始）；{{current===items.length?'全部完成':'进行中'}}</output></div></template>